const BASE_URL = process.env.REACT_APP_API_URL || "/api/v1/ai";

async function parseResponse(response) {
  const contentType = response.headers.get("content-type") || "";
  if (contentType.includes("application/json")) {
    return response.json();
  }
  return response.text();
}

export async function checkHealth() {
  const response = await fetch(`${BASE_URL}/health`);
  const body = await parseResponse(response);
  if (!response.ok) {
    throw new Error(typeof body === "string" ? body : "Health check failed");
  }
  return body;
}

export async function sendPrompt({ prompt, mode, sessionId }) {
  const payload = {
    provider: "copilot",
    prompt,
    mode
  };

  if (sessionId) {
    payload.sessionId = sessionId;
  }

  if (mode === "agent") {
    payload.enabledTools = ["all"];
  }

  const response = await fetch(`${BASE_URL}/prompt`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload)
  });

  const body = await parseResponse(response);
  if (!response.ok) {
    const errorMessage = typeof body === "string"
      ? body
      : body?.message || body?.error || `Request failed with status ${response.status}`;
    throw new Error(errorMessage);
  }

  return body;
}
